$ErrorActionPreference = "Stop"

$ProjectRoot = "H:\MNTrapTeam\MNTrapTeam"
$Version = "4.7.1"

if (-not (Test-Path (Join-Path $ProjectRoot "mntrapteam"))) {
    throw "MNTrapTeam project not found at $ProjectRoot"
}

Write-Host "Installing MNTrapTeam $Version MyATA reconciliation fix..."

$payload = ""
[IO.File]::WriteAllBytes(
    (Join-Path $ProjectRoot "mntrapteam\central_zone_import_cli.py"),
    [Convert]::FromBase64String($payload)
)

Set-Content -Path (Join-Path $ProjectRoot "VERSION") -Value $Version -Encoding UTF8

Set-Location $ProjectRoot
& ".\.venv\Scripts\python.exe" -m py_compile ".\mntrapteam\central_zone_import_cli.py"
if ($LASTEXITCODE -ne 0) { throw "Syntax check failed." }

Write-Host ""
Write-Host "MNTrapTeam 4.7.1 installed."
Write-Host "Latest MyATA date is no longer treated as proof that all earlier shoots are official."
Write-Host "Older source rows are now shown in a reconciliation section instead of silently dropped."
Write-Host ""
Write-Host "Next:"
Write-Host '& ".\.venv\Scripts\python.exe" -m mntrapteam.central_zone_import_cli preview'
